INSERT INTO canonical_system_roles (slug, name, description, module_key, risk_level, assignable) VALUES
  ('accountant', 'Accountant', 'Journal preparation, receivables, payables and routine accounting operations without approval authority.', 'accounting', 'sensitive', true),
  ('accounts_payable_executive', 'Accounts Payable Executive', 'Supplier bills, matching and payment preparation without payment approval.', 'accounting', 'sensitive', true),
  ('accounts_receivable_executive', 'Accounts Receivable Executive', 'Customer invoices, receipts, allocations, disputes and collections.', 'accounting', 'sensitive', true),
  ('asset_manager', 'Asset Manager', 'Asset register, capitalization, custody, maintenance, depreciation, audits, transfers and disposal.', 'assets', 'sensitive', true),
  ('auditor', 'Auditor', 'Read-only governance, audit and released-module reporting access.', 'platform', 'sensitive', true),
  ('buyer', 'Buyer / Purchase Officer', 'Supplier enquiries, sourcing, contracts and purchase-order preparation without approval authority.', 'procurement', 'sensitive', true),
  ('company_administrator', 'Company Administrator', 'Delegated company, branch and user administration inside explicitly granted companies and branches. No business-module, module-enablement, role-definition or billing authority.', 'platform', 'privileged', true),
  ('crm_administrator', 'CRM Administrator', 'CRM configuration, integrations, data quality, automation and administration.', 'crm', 'privileged', true),
  ('customer_success_manager', 'Customer Success Manager', 'Customer health, success plans, renewals, feedback, playbooks and account engagement.', 'crm', 'standard', true),
  ('employee', 'Employee', 'Basic employee access. Business permissions must be added through another role.', 'platform', 'standard', true),
  ('finance_manager', 'Finance Manager', 'Finance governance, period close, budgets, taxes, policies and accounting approvals.', 'accounting', 'privileged', true),
  ('goods_receipt_user', 'Goods Receipt User', 'Record receipts, inspections, discrepancies and supplier returns.', 'procurement', 'standard', true),
  ('hr_manager', 'HR Manager', 'Employees, attendance, leave, expenses, compensation, payroll, payslips and statutory controls.', 'hr-payroll', 'sensitive', true),
  ('inventory_manager', 'Inventory Manager', 'Warehouse operations, stock movements, transfers, counts, valuation and replenishment.', 'stock', 'sensitive', true),
  ('manufacturing_manager', 'Manufacturing Manager', 'BOMs, routings, work centers, material planning, work orders, production execution and costing.', 'manufacturing', 'sensitive', true),
  ('marketing_manager', 'Marketing Manager', 'Campaigns, segments, journeys, forms, events, attribution and marketing integrations.', 'crm', 'sensitive', true),
  ('organization_owner', 'Organisation Owner', 'Full organisation ownership and governance.', 'platform', 'privileged', false),
  ('partner_manager', 'Partner Manager', 'Partner onboarding, deal registration, MDF, partner performance and field engagement.', 'crm', 'sensitive', true),
  ('pos_cashier', 'POS Cashier', 'Least-privilege checkout operation: open/close an assigned shift, ring up sales, request returns. No overrides, no approvals, no store/terminal configuration.', 'point-of-sale', 'standard', true),
  ('pos_manager', 'Point of Sale Manager', 'Stores, terminals, checkout, payments, returns, cashier shifts and reconciliation.', 'point-of-sale', 'sensitive', true),
  ('pos_supervisor', 'POS Supervisor', 'Store-floor override authority: approve returns, apply discounts and price overrides, adjust cash, view reports. Does not create returns itself and does not configure stores/terminals/settings.', 'point-of-sale', 'sensitive', true),
  ('project_manager', 'Project Manager', 'Projects, milestones, tasks, resourcing, time, expenses, budgets, billing and profitability.', 'projects', 'sensitive', true),
  ('purchase_approver', 'Purchase Approver', 'Approve requisitions, contracts and purchase orders without creating or dispatching them.', 'procurement', 'privileged', true),
  ('purchase_manager', 'Procurement Manager', 'Procurement governance, supplier lifecycle, sourcing, contracts and purchasing approvals.', 'procurement', 'privileged', true),
  ('purchase_requester', 'Purchase Requester', 'Create and track purchase requisitions within assigned organisational scope.', 'procurement', 'standard', true),
  ('quality_manager', 'Quality Manager', 'Quality plans, inspections, holds, non-conformance, CAPA, supplier quality and audits.', 'quality', 'sensitive', true),
  ('read_only', 'Read-only User', 'Read-only access to the released business modules and reports within assigned companies and branches.', 'platform', 'standard', true),
  ('sales_head', 'Sales Head', 'Organisation-wide sales leadership, forecasts, approvals, targets and commercial governance.', 'sales', 'privileged', true),
  ('sales_manager', 'Sales Manager', 'Team pipeline, opportunities, forecasts, quotations and sales approvals.', 'sales', 'sensitive', true),
  ('sales_operations', 'Sales Operations', 'Sales data quality, assignment, imports, configuration and reporting without commercial approval authority.', 'sales', 'sensitive', true),
  ('sales_representative', 'Sales Representative', 'Manage assigned leads, accounts, opportunities, activities, quotations and sales orders.', 'sales', 'standard', true),
  ('supplier_manager', 'Supplier Manager', 'Supplier onboarding, qualification, catalogues, sensitive details and performance records.', 'procurement', 'sensitive', true),
  ('support_manager', 'Support Manager', 'Tickets, queues, SLAs, escalation, knowledge base and customer communication.', 'support', 'sensitive', true),
  ('system_administrator', 'System Administrator', 'Platform configuration, security and access administration.', 'platform', 'privileged', true),
  ('tax_compliance_accountant', 'Tax and Compliance Accountant', 'Tax setup, returns, compliance evidence, FX reporting and audit support.', 'accounting', 'sensitive', true),
  ('treasury_executive', 'Treasury Executive', 'Payment execution, bank accounts, statements, reconciliation and cash operations without payment approval.', 'accounting', 'privileged', true);
